1	<!doctype html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Tetris</title>
7	<style>
8	  :root {
9	    --bg: #111418;
10	    --panel: #1b2027;
11	    --grid: #232a33;
12	    --text: #e8ecf1;
13	    --muted: #8b96a5;
14	    --I: #22c7e8;
15	    --O: #f2c613;
16	    --T: #a64ee0;
17	    --S: #3fc15a;
18	    --Z: #e8453c;
19	    --J: #3a6fe8;
20	    --L: #f08a24;
21	  }
22	  * { box-sizing: border-box; }
23	  body {
24	    margin: 0;
25	    min-height: 100vh;
26	    background: var(--bg);
27	    color: var(--text);
28	    font: 15px/1.4 system-ui, -apple-system, "Segoe UI", sans-serif;
29	    display: flex;
30	    align-items: center;
31	    justify-content: center;
32	    padding: 16px;
33	  }
34	  .game { display: flex; gap: 20px; align-items: flex-start; flex-wrap: wrap; justify-content: center; }
35	  .board {
36	    display: grid;
37	    grid-template-columns: repeat(10, 28px);
38	    grid-template-rows: repeat(20, 28px);
39	    gap: 1px;
40	    background: var(--grid);
41	    border: 2px solid var(--grid);
42	    border-radius: 4px;
43	  }
44	  .cell { background: var(--bg); }
45	  .side { display: flex; flex-direction: column; gap: 12px; min-width: 140px; }
46	  .box { background: var(--panel); border-radius: 6px; padding: 10px 12px; }
47	  .label { color: var(--muted); font-size: 12px; text-transform: uppercase; letter-spacing: .08em; }
48	  .value { font-size: 22px; font-weight: 600; font-variant-numeric: tabular-nums; }
49	  .preview {
50	    display: grid;
51	    grid-template-columns: repeat(4, 20px);
52	    grid-template-rows: repeat(2, 20px);
53	    gap: 1px;
54	    margin-top: 6px;
55	  }
56	  .preview div { background: transparent; }
57	  .next-list { display: flex; flex-direction: column; gap: 8px; }
58	  .board-wrap { position: relative; }
59	  .game-over, .paused {
60	    position: absolute; inset: 0; display: flex; align-items: center; justify-content: center;
61	    background: rgba(17, 20, 24, .78); font-size: 24px; font-weight: 600; border-radius: 4px;
62	  }
63	  .cell[data-ghost="true"] { box-shadow: inset 0 0 0 2px var(--muted); }
64	  .p-I { background: var(--I) !important; }
65	  .p-O { background: var(--O) !important; }
66	  .p-T { background: var(--T) !important; }
67	  .p-S { background: var(--S) !important; }
68	  .p-Z { background: var(--Z) !important; }
69	  .p-J { background: var(--J) !important; }
70	  .p-L { background: var(--L) !important; }
71	  button {
72	    background: var(--panel); color: var(--text); border: 1px solid var(--grid);
73	    border-radius: 6px; padding: 8px 12px; font: inherit; cursor: pointer;
74	  }
75	  button:hover { border-color: var(--muted); }
76	  .keys { color: var(--muted); font-size: 13px; }
77	</style>
78	</head>
79	<body>
80	<div class="game">
81	  <div class="board-wrap">
82	    <div class="board" data-testid="board" id="board"></div>
83	    <div class="game-over" data-testid="game-over" id="game-over" hidden>Game over</div>
84	    <div class="paused" data-testid="paused-indicator" id="paused" hidden>Paused</div>
85	  </div>
86	  <div class="side">
87	    <div class="box"><div class="label">Score</div><div class="value" data-testid="score" id="score">0</div></div>
88	    <div class="box"><div class="label">Level</div><div class="value" data-testid="level" id="level">1</div></div>
89	    <div class="box"><div class="label">Lines</div><div class="value" data-testid="lines" id="lines">0</div></div>
90	    <div class="box"><div class="label">Hold</div><div class="preview" data-testid="hold-piece" data-piece="" id="hold"></div></div>
91	    <div class="box"><div class="label">Next</div><div class="next-list" data-testid="next-piece" id="preview"></div></div>
92	    <button data-testid="pause-btn" id="pause" type="button">Pause</button>
93	    <button id="restart" type="button">New game</button>
94	    <div class="keys">← → move<br>↑ rotate<br>↓ soft drop<br>Space hard drop<br>C hold<br>P pause</div>
95	  </div>
96	</div>
97	<script>
98	(function () {
99	  "use strict";
100	
101	  var ROWS = 20, COLS = 10;
102	  var TYPES = ["I", "O", "T", "S", "Z", "J", "L"];
103	
104	  // Spawn shapes as [row, col] offsets from the piece origin.
105	  var SHAPES = {
106	    I: [[0, 0], [0, 1], [0, 2], [0, 3]],
107	    O: [[0, 1], [0, 2], [1, 1], [1, 2]],
108	    T: [[0, 1], [1, 0], [1, 1], [1, 2]],
109	    S: [[0, 1], [0, 2], [1, 0], [1, 1]],
110	    Z: [[0, 0], [0, 1], [1, 1], [1, 2]],
111	    J: [[0, 0], [1, 0], [1, 1], [1, 2]],
112	    L: [[0, 2], [1, 0], [1, 1], [1, 2]]
113	  };
114	  // Side length of the square each shape rotates within.
115	  var BOX = { I: 4, O: 2, T: 3, S: 3, Z: 3, J: 3, L: 3 };
116	  var SPAWN_COL = 3;
117	  // Level rule (project decision): level starts at 1 and rises by one for every
118	  // LINES_PER_LEVEL lines cleared; it never goes down. Gravity interval in ms is
119	  // max(MIN_GRAVITY_MS, BASE_GRAVITY_MS - (level - 1) * GRAVITY_STEP_MS).
120	  // __tetris.tick(n) always advances exactly n gravity steps, whatever the level.
121	  var LINES_PER_LEVEL = 10;
122	  var BASE_GRAVITY_MS = 1000;
123	  var GRAVITY_STEP_MS = 100;
124	  var MIN_GRAVITY_MS = 100;
125	  // Hold rule (project decision): one slot. Holding with an empty slot sets the
126	  // falling piece aside and spawns the next one; otherwise it swaps with the held
127	  // piece, which enters at the spawn position. One hold per piece: a second hold
128	  // is refused until a piece locks.
129	  // Preview rule (project decision): show only the next piece, in its board colour.
130	  var PREVIEW_COUNT = 1;
131	
132	  // Locking rule (project decision): a gravity step that cannot move the piece
133	  // down counts one lock tick; the piece locks on the LOCK_TICKS-th tick.
134	  // Left/right while resting restarts the delay, at most MAX_LOCK_RESETS times
135	  // per piece. Soft drop on a resting piece restarts it too, from the same
136	  // per-piece allowance. Hard drop locks at once.
137	  var LOCK_TICKS = 2;
138	  var MAX_LOCK_RESETS = 3;
139	  // Pause rule (project decision): "pause" toggles between running and paused.
140	  // While paused, gravity steps and player actions do nothing. Pausing keeps the
141	  // piece's lock ticks and lock resets as they were, and does not restart the
142	  // gravity timer, so pausing and resuming cannot postpone a lock.
143	  // Rotation tries these sideways shifts, in order, until one fits.
144	  var KICKS = [0, -1, 1, -2, 2];
145	
146	  // Scoring rule (project decision): a clear scores CLEAR_POINTS[rows] x level.
147	  // Clearing rows together must always beat clearing them one at a time.
148	  // Soft drop scores 1 per cell moved by the player (gravity scores nothing);
149	  // hard drop scores 2 per cell dropped. Drop points are not multiplied.
150	  var CLEAR_POINTS = [0, 100, 300, 500, 800];
151	  var SOFT_DROP_POINTS = 1;
152	  var HARD_DROP_POINTS = 2;
153	
154	  var state = {
155	    board: [],      // ROWS x COLS, "" or piece letter
156	    current: null,  // { type, row, col, shape, lockTicks, lockResets }
157	    next: [],
158	    hold: null,     // held piece letter or null
159	    canHold: true,
160	    score: 0,
161	    level: 1,
162	    lines: 0,
163	    status: "running"
164	  };
165	
166	  // ---- core logic ----
167	
168	  function emptyBoard() {
169	    var b = [];
170	    for (var r = 0; r < ROWS; r++) {
171	      var row = [];
172	      for (var c = 0; c < COLS; c++) row.push("");
173	      b.push(row);
174	    }
175	    return b;
176	  }
177	
178	  function randomType() {
179	    return TYPES[Math.floor(Math.random() * TYPES.length)];
180	  }
181	
182	  function cellsOf(piece, dRow, dCol) {
183	    return piece.shape.map(function (o) {
184	      return [piece.row + (dRow || 0) + o[0], piece.col + (dCol || 0) + o[1]];
185	    });
186	  }
187	
188	  function fits(piece, dRow, dCol) {
189	    return cellsOf(piece, dRow, dCol).every(function (p) {
190	      return p[0] >= 0 && p[0] < ROWS && p[1] >= 0 && p[1] < COLS && state.board[p[0]][p[1]] === "";
191	    });
192	  }
193	
194	  function dropInterval() {
195	    return Math.max(MIN_GRAVITY_MS, BASE_GRAVITY_MS - (state.level - 1) * GRAVITY_STEP_MS);
196	  }
197	
198	  function spawn() {
199	    var type = state.next.length ? state.next.shift() : randomType();
200	    while (state.next.length < PREVIEW_COUNT) state.next.push(randomType());
201	    spawnType(type);
202	  }
203	
204	  function spawnType(type) {
205	    var piece = { type: type, row: 0, col: SPAWN_COL, shape: SHAPES[type], lockTicks: 0, lockResets: 0 };
206	    // Game over: the new piece has nowhere to go. It is not placed.
207	    if (!fits(piece, 0, 0)) {
208	      state.current = null;
209	      state.status = "gameover";
210	      return;
211	    }
212	    state.current = piece;
213	  }
214	
215	  function lock() {
216	    var piece = state.current;
217	    cellsOf(piece).forEach(function (p) { state.board[p[0]][p[1]] = piece.type; });
218	    state.current = null;
219	    state.canHold = true;
220	    clearLines();
221	    spawn();
222	  }
223	
224	  // Remove every full row; rows above drop down. Scores the clear.
225	  function clearLines() {
226	    var kept = state.board.filter(function (row) {
227	      return row.some(function (t) { return t === ""; });
228	    });
229	    var cleared = ROWS - kept.length;
230	    if (!cleared) return;
231	    while (kept.length < ROWS) kept.unshift(emptyBoard()[0]);
232	    state.board = kept;
233	    var before = Math.floor(state.lines / LINES_PER_LEVEL);
234	    state.lines += cleared;
235	    state.score += CLEAR_POINTS[cleared] * state.level;
236	    var gained = Math.floor(state.lines / LINES_PER_LEVEL) - before;
237	    if (gained > 0) {
238	      state.level += gained;
239	      restartTimer();
240	    }
241	  }
242	
243	  // Cells the falling piece would occupy if dropped straight down now.
244	  function ghostCells() {
245	    if (!state.current) return [];
246	    var d = 0;
247	    while (fits(state.current, d + 1, 0)) d++;
248	    return cellsOf(state.current, d, 0);
249	  }
250	
251	  function tryMove(dRow, dCol) {
252	    if (!state.current || !fits(state.current, dRow, dCol)) return false;
253	    state.current.row += dRow;
254	    state.current.col += dCol;
255	    if (dRow > 0) state.current.lockTicks = 0;
256	    return true;
257	  }
258	
259	  // If the lock delay is running, restart it (capped per piece).
260	  function resetLockDelay(piece) {
261	    if (piece.lockTicks > 0 && piece.lockResets < MAX_LOCK_RESETS) {
262	      piece.lockResets++;
263	      piece.lockTicks = 0;
264	    }
265	  }
266	
267	  function shift(dCol) {
268	    var piece = state.current;
269	    if (!tryMove(0, dCol)) return;
270	    resetLockDelay(piece);
271	  }
272	
273	  function rotateCW() {
274	    var piece = state.current;
275	    if (!piece || piece.type === "O") return;
276	    var n = BOX[piece.type];
277	    var turned = {
278	      type: piece.type, row: piece.row, col: piece.col,
279	      shape: piece.shape.map(function (o) { return [o[1], n - 1 - o[0]]; })
280	    };
281	    for (var i = 0; i < KICKS.length; i++) {
282	      if (fits(turned, 0, KICKS[i])) {
283	        piece.shape = turned.shape;
284	        piece.col += KICKS[i];
285	        return;
286	      }
287	    }
288	  }
289	
290	  // One gravity step. The timer and __tetris.tick both call this.
291	  function gravityStep() {
292	    if (state.status !== "running" || !state.current) return;
293	    if (tryMove(1, 0)) return;
294	    state.current.lockTicks++;
295	    if (state.current.lockTicks >= LOCK_TICKS) lock();
296	  }
297	
298	  var actions = {
299	    left: function () { if (state.current) shift(-1); },
300	    right: function () { if (state.current) shift(1); },
301	    rotateCW: rotateCW,
302	    softDrop: function () {
303	      if (!state.current) return;
304	      if (tryMove(1, 0)) state.score += SOFT_DROP_POINTS;
305	      else resetLockDelay(state.current);
306	    },
307	    hardDrop: function () {
308	      if (!state.current) return;
309	      while (tryMove(1, 0)) state.score += HARD_DROP_POINTS;
310	      lock();
311	    },
312	    hold: function () {
313	      if (!state.current || !state.canHold) return;
314	      var type = state.current.type;
315	      state.canHold = false;
316	      if (state.hold) {
317	        var held = state.hold;
318	        state.hold = type;
319	        spawnType(held);
320	      } else {
321	        state.hold = type;
322	        spawn();
323	      }
324	    }
325	  };
326	
327	  // Only flips the status. Lock state and the timer are left untouched.
328	  function togglePause() {
329	    if (state.status === "running") state.status = "paused";
330	    else if (state.status === "paused") state.status = "running";
331	  }
332	
333	  function doAction(name) {
334	    if (name === "pause") {
335	      togglePause();
336	      render();
337	      return;
338	    }
339	    if (state.status !== "running" || !actions[name]) return;
340	    actions[name]();
341	    render();
342	  }
343	
344	  function newGame(queue) {
345	    state.board = emptyBoard();
346	    state.score = 0;
347	    state.level = 1;
348	    state.lines = 0;
349	    state.hold = null;
350	    state.canHold = true;
351	    state.status = "running";
352	    state.next = Array.isArray(queue) ? queue.slice() : [];
353	    spawn();
354	    restartTimer();
355	    render();
356	  }
357	
358	  // ---- rendering (synchronous) ----
359	
360	  var boardEl = document.getElementById("board");
361	  var previewEl = document.getElementById("preview");
362	  var scoreEl = document.getElementById("score");
363	  var levelEl = document.getElementById("level");
364	  var linesEl = document.getElementById("lines");
365	  var gameOverEl = document.getElementById("game-over");
366	  var holdEl = document.getElementById("hold");
367	  var pausedEl = document.getElementById("paused");
368	  var pauseBtn = document.getElementById("pause");
369	  var cellEls = [];
370	  var holdCells = [];
371	  for (var h = 0; h < 8; h++) holdCells.push(holdEl.appendChild(document.createElement("div")));
372	
373	  (function buildDom() {
374	    for (var r = 0; r < ROWS; r++) {
375	      var row = [];
376	      for (var c = 0; c < COLS; c++) {
377	        var el = document.createElement("div");
378	        el.className = "cell";
379	        el.setAttribute("data-testid", "cell");
380	        el.setAttribute("data-row", String(r));
381	        el.setAttribute("data-col", String(c));
382	        el.setAttribute("data-filled", "false");
383	        el.setAttribute("data-piece", "");
384	        el.setAttribute("data-ghost", "false");
385	        boardEl.appendChild(el);
386	        row.push(el);
387	      }
388	      cellEls.push(row);
389	    }
390	  })();
391	
392	  // One preview item per previewed piece, drawn in its board colour.
393	  function previewItem(type) {
394	    var item = document.createElement("div");
395	    item.className = "preview";
396	    item.setAttribute("data-testid", "next-piece-item");
397	    item.setAttribute("data-piece", type);
398	    var cells = [];
399	    for (var i = 0; i < 8; i++) cells.push(item.appendChild(document.createElement("div")));
400	    SHAPES[type].forEach(function (o) { paint(cells[o[0] * 4 + o[1]], type); });
401	    return item;
402	  }
403	
404	  function paint(el, type) {
405	    el.className = el.className.replace(/\s*p-[A-Z]/g, "") + (type ? " p-" + type : "");
406	  }
407	
408	  function render() {
409	    var view = state.board.map(function (row) { return row.slice(); });
410	    var ghost = state.board.map(function (row) { return row.map(function () { return false; }); });
411	    ghostCells().forEach(function (p) { ghost[p[0]][p[1]] = true; });
412	    if (state.current) {
413	      cellsOf(state.current).forEach(function (p) {
414	        if (p[0] >= 0 && p[0] < ROWS && p[1] >= 0 && p[1] < COLS) view[p[0]][p[1]] = state.current.type;
415	      });
416	    }
417	    for (var r = 0; r < ROWS; r++) {
418	      for (var c = 0; c < COLS; c++) {
419	        var el = cellEls[r][c], t = view[r][c];
420	        el.setAttribute("data-filled", t ? "true" : "false");
421	        el.setAttribute("data-piece", t);
422	        // A ghost cell covered by the falling piece shows the piece, not the ghost.
423	        el.setAttribute("data-ghost", ghost[r][c] && !t ? "true" : "false");
424	        paint(el, t);
425	      }
426	    }
427	    previewEl.textContent = "";
428	    state.next.slice(0, PREVIEW_COUNT).forEach(function (type) {
429	      if (SHAPES[type]) previewEl.appendChild(previewItem(type));
430	    });
431	    holdEl.setAttribute("data-piece", state.hold || "");
432	    holdCells.forEach(function (el) { paint(el, ""); });
433	    if (state.hold) SHAPES[state.hold].forEach(function (o) { paint(holdCells[o[0] * 4 + o[1]], state.hold); });
434	    gameOverEl.hidden = state.status !== "gameover";
435	    pausedEl.hidden = state.status !== "paused";
436	    pauseBtn.textContent = state.status === "paused" ? "Resume" : "Pause";
437	    pauseBtn.disabled = state.status === "gameover";
438	    scoreEl.textContent = String(state.score);
439	    levelEl.textContent = String(state.level);
440	    linesEl.textContent = String(state.lines);
441	  }
442	
443	  // ---- timer ----
444	
445	  var timer = null;
446	  function onTimer() { gravityStep(); render(); }
447	  function restartTimer() {
448	    if (timer) clearInterval(timer);
449	    timer = setInterval(onTimer, dropInterval());
450	  }
451	
452	  // ---- input ----
453	
454	  var KEYS = { ArrowLeft: "left", ArrowRight: "right", ArrowDown: "softDrop", ArrowUp: "rotateCW", " ": "hardDrop", c: "hold", C: "hold", p: "pause", P: "pause" };
455	  document.addEventListener("keydown", function (e) {
456	    var action = KEYS[e.key];
457	    if (!action) return;
458	    e.preventDefault();
459	    doAction(action);
460	  });
461	  pauseBtn.addEventListener("click", function (e) {
462	    e.currentTarget.blur();
463	    doAction("pause");
464	  });
465	  document.getElementById("restart").addEventListener("click", function (e) {
466	    e.currentTarget.blur();
467	    newGame();
468	  });
469	
470	  // ---- test control surface ----
471	
472	  window.__tetris = {
473	    newGame: function (queue) { newGame(queue); },
474	    setQueue: function (queue) {
475	      state.next = Array.isArray(queue) ? queue.slice() : [];
476	      render();
477	    },
478	    setBoard: function (rows) {
479	      state.board = rows.map(function (line) {
480	        return line.split("").map(function (ch) { return ch === "." ? "" : ch; });
481	      });
482	      render();
483	    },
484	    tick: function (n) {
485	      var steps = n === undefined ? 1 : n;
486	      for (var i = 0; i < steps; i++) gravityStep();
487	      render();
488	    },
489	    setLevel: function (n) {
490	      state.level = n;
491	      restartTimer();
492	      render();
493	    },
494	    input: function (action) { doAction(action); },
495	    getBoard: function () {
496	      return state.board.map(function (row) {
497	        return row.map(function (t) { return t || "."; }).join("");
498	      });
499	    },
500	    getState: function () {
501	      return {
502	        current: state.current
503	          ? { type: state.current.type, cells: cellsOf(state.current) }
504	          : null,
505	        next: state.next.slice(),
506	        ghost: ghostCells(),
507	        score: state.score,
508	        level: state.level,
509	        dropInterval: dropInterval(),
510	        hold: state.hold,
511	        lines: state.lines,
512	        status: state.status
513	      };
514	    }
515	  };
516	
517	  newGame();
518	})();
519	</script>
520	</body>
521	</html>
